<?php
require __DIR__.'/../app/bootstrap.php';
$me=require_login();if($me['role']!=='owner'){http_response_code(403);exit('Owner access required');}
$rows=$pdo->query('SELECT d.id,d.occurred_at,u.username,d.ip_address,d.user_agent,d.reason,d.requested_path FROM panel_access_denials d LEFT JOIN users u ON u.id=d.user_id ORDER BY d.occurred_at DESC LIMIT 250')->fetchAll();
?><!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Denied Staff Access</title><link rel="stylesheet" href="style.css"><main><a href="dashboard.php">← Dashboard</a><h1>Denied Staff Access</h1><p>Recent denied role checks. Times are stored using the server's configured time zone. Protect IP addresses and minimise retention.</p><section class="panel"><div class="tablewrap"><table><thead><tr><th>Time</th><th>Account</th><th>IP</th><th>Reason</th><th>Page</th><th>Browser</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h($r['occurred_at'])?></td><td><?=h($r['username']??'Unknown')?></td><td><?=h($r['ip_address'])?></td><td><?=h($r['reason'])?></td><td><?=h($r['requested_path'])?></td><td><?=h($r['user_agent'])?></td></tr><?php endforeach;?></tbody></table></div></section></main></html>
